    size_t i;
    adcs_vec3_t axis;
    adcs_status_t st;

    if ((momentum == NULL) || (momentum_norm == NULL) || (energy_axis == NULL) || (energy == NULL)) {
        return ADCS_E_NULL;
    }

    *momentum = (adcs_vec3_t){0, 0, 0};
    *momentum_norm = 0.0;
    *energy_axis = (adcs_vec3_t){0, 0, 0};
    *energy = 0.0;

    if (wheels == NULL) {
        return ADCS_E_NULL;
    }

    if ((count < 1U) || (count > 16U)) {
        return ADCS_E_RANGE;
    }

    for (i = 0; i < count; i++) {
        double e;
        adcs_vec3_t term;

        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0) ||
            (!isfinite(wheels[i].speed_rad_s)) ||
            (!adcs_is_finite_vec3(&wheels[i].axis_body))) {
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        e = 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;
        *energy += e;
        term = adcs_vec3_scale(&axis, e);
        *energy_axis = adcs_vec3_add(energy_axis, &term);
    }

    st = adcs_wheel_momentum(wheels, count, momentum);
    if (st != ADCS_OK) {
        return st;
    }

    *momentum_norm = adcs_vec3_norm(momentum);
}

